//! Integration test suite for Sovereign ReactOS & Linux Distribution Innovations V82 PR Gateway.

#[path = "../src/distro/reactos_linux_distro_innovations_v82_pr.rs"]
mod reactos_linux_distro_innovations_v82_pr;

use reactos_linux_distro_innovations_v82_pr::*;

#[test]
fn test_reactos_linux_distro_innovations_v82_pr_integration() {
    let mut gateway = SovereignReactOsLinuxInnovationsV82PrGateway::new();

    // Verify all 6 manifests generated by gateway
    let manifests = gateway.collect_all_manifests();
    assert_eq!(manifests.len(), 6);

    for manifest in &manifests {
        assert!(manifest.pr_id >= 4091 && manifest.pr_id <= 4096);
        assert!(!manifest.pr_title.is_empty());
        assert!(!manifest.target_subsystem.is_empty());
        assert_eq!(manifest.status, "Ready for Integration");
    }

    // Verify LPC Port Engine
    let port_handle = gateway
        .lpc_engine
        .create_port("\\LpcPort\\LsaAuthenticationPort", 256)
        .unwrap();
    assert_eq!(port_handle, 0x2004);

    let lpc_req = gateway
        .lpc_engine
        .send_request_wait_reply(100, b"AUTH_REQUEST")
        .unwrap();
    assert_eq!(lpc_req.data_length, 12);

    // Verify KMDF Driver Dispatcher Engine
    let drv_reg = gateway.kmdf_engine.register_driver(
        "\\Driver\\Audio",
        "\\Device\\Audio0",
        0x0000001D,
    );
    assert!(drv_reg.is_ok());

    let irp_disp = gateway
        .kmdf_engine
        .dispatch_irp("\\Driver\\Audio", 0x00)
        .unwrap();
    assert!(irp_disp.contains("KmdfGenericCreate"));

    // Verify PE TLS Relocation Engine
    gateway
        .pe_tls_engine
        .bind_iat_function("User32.dll!MessageBoxW", 0x77801000);
    assert_eq!(
        gateway.pe_tls_engine.iat_bindings.get("User32.dll!MessageBoxW"),
        Some(&0x77801000)
    );

    let callbacks_run = gateway.pe_tls_engine.execute_tls_callbacks(1);
    assert_eq!(callbacks_run, 1);

    // Verify Shell Tray Explorer Engine
    assert!(gateway
        .shell_engine
        .add_tray_icon(0x00050050, 5, "Volume Control"));
    assert_eq!(gateway.shell_engine.active_icons.len(), 2);

    // Verify win32k GDI Font Engine
    let font_handle = gateway
        .gdi_font_engine
        .create_font("Courier New", 14, 400, false);
    assert_eq!(font_handle, 0x1004);

    let font_rec = gateway.gdi_font_engine.lookup_font(font_handle).unwrap();
    assert_eq!(font_rec.font_name, "Courier New");

    // Verify HAL PCI Driver Engine
    let irq = gateway
        .hal_pci_engine
        .hal_get_interrupt_vector(0, 1)
        .unwrap();
    assert_eq!(irq, 11);

    // Execute full evaluation pipeline
    assert!(gateway.execute_reactos_v82_evaluation());
}
